// Editorial, age-appropriate next steps. Not eligibility or admissions guarantees.
export const planningGuidance={
 physician:{try:['Explore a health question','Use two reliable sources to explain a general health question. Notice whether you enjoy the science, explanation, or both. Try a supervised healthcare activity through a youth program.'],prepare:['Map college, medical school, and residency','Compare college prerequisites, four-year medical training, and family medicine residency. Budget each stage separately; no college major guarantees medical school admission.'],talk:['Ask about a normal day in family medicine','Ask a physician and a resident about patient contact, paperwork, training hours, and what they wish they knew in high school.']},
 dentist:{try:['Try a safe hand-skills and design project','Make a small clay model or detailed illustration. Notice whether you enjoy careful, detailed handwork. This is exploration, not a dental aptitude test.'],prepare:['Map college prerequisites and dental school','Compare college, dental school, and Texas licensing. Include instruments, clinical fees, living costs, and possible loan payments.'],talk:['Ask a dentist about the everyday work','Ask about patient anxiety, repetitive procedures, hand skills, employee pay, and the difference between a dental practice’s sales and the dentist’s own pay.']},
 'graphic-design':{try:['Build three pieces for a small portfolio','Design a poster, a simple logo and matching colors, and a digital layout. Ask for feedback and revise one piece. Notice whether feedback and changes hold your interest.'],prepare:['Compare affordable design programs','Compare classes, portfolio requirements, internships, software, cost after grants, and transfer credits. College can build skills and connections; your portfolio still matters for hiring.'],talk:['Ask an employed designer about early-career work','Ask about deadlines, client feedback, portfolio expectations, and full-time roles versus freelance hours and business expenses.']},
 electrician:{try:['Explore electrical work safely','Visit a public training demonstration or approved student program. Practice algebra, measurement, and reading diagrams. Do not work on live wiring.'],prepare:['Compare a paid apprenticeship and college options','Austin ETA combines four years and 8,000 hours of training. Review admission steps, published pay, tuition, tools, and Texas licensing. Compare technical college classes and construction-management study too.'],talk:['Ask an apprentice and a qualified electrician','Ask about hours, travel to job sites, physical demands, tuition, and how pay changes with completed training. Ask which pay figures are that employer’s rates and which are area-wide estimates.']}
};
